function demoMain(idx,label){
  var specs=[["GET /users","200 array",true],["POST /orders","201 object",true],["GET /secret","200",false]];
  var s=specs[idx%specs.length];
  return "["+label+"] contract "+s[0]+" expects "+s[1]+" => "+(s[2]?"MATCH":"MISMATCH: auth required");
}

